-- +goose Up

-- Conventions (docs/ARCHITECTURE.md §4):
--   * ids are uuid, generated by uuidv7() so they sort by creation time;
--   * timestamps are timestamptz, stored in UTC;
--   * money is NUMERIC(12,2), quantities are NUMERIC(12,3);
--   * every user-owned table carries user_id, and a reference between two
--     user-owned tables is a composite foreign key that includes user_id, so
--     a row can never point at a row of another user;
--   * ON DELETE NO ACTION is used where a delete must be refused. RESTRICT
--     would also refuse the cascade that removes a whole user.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- People who may sign in. A row is created on the first admitted sign-in.
CREATE TABLE users (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    google_sub text        NOT NULL,
    email      text        NOT NULL,
    name       text        NOT NULL DEFAULT '',
    is_admin   boolean     NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_google_sub_key UNIQUE (google_sub),
    CONSTRAINT users_google_sub_check CHECK (google_sub <> ''),
    CONSTRAINT users_email_check CHECK (email <> '')
);

CREATE TABLE user_settings (
    user_id               uuid        PRIMARY KEY,
    default_currency      text        NOT NULL DEFAULT 'TRY',
    default_receipt_title text        NOT NULL DEFAULT 'Home shopping',
    updated_at            timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT user_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT user_settings_default_currency_check CHECK (default_currency ~ '^[A-Z]{3}$'),
    CONSTRAINT user_settings_default_receipt_title_check CHECK (btrim(default_receipt_title) <> '')
);

-- Session store of alexedwards/scs (pgxstore). The library owns the layout.
CREATE TABLE sessions (
    token  text        PRIMARY KEY,
    data   bytea       NOT NULL,
    expiry timestamptz NOT NULL
);

CREATE INDEX sessions_expiry_idx ON sessions (expiry);

CREATE TABLE stores (
    id              uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id         uuid        NOT NULL,
    name            text        NOT NULL,
    normalized_name text        NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT stores_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT stores_user_id_id_key UNIQUE (user_id, id),
    CONSTRAINT stores_user_id_normalized_name_key UNIQUE (user_id, normalized_name),
    CONSTRAINT stores_name_check CHECK (btrim(name) <> ''),
    CONSTRAINT stores_normalized_name_check CHECK (normalized_name <> '')
);

CREATE TABLE categories (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id    uuid        NOT NULL,
    name       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT categories_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT categories_user_id_id_key UNIQUE (user_id, id),
    CONSTRAINT categories_name_check CHECK (btrim(name) <> '')
);

-- "Dairy" and "dairy" are the same category to a person.
CREATE UNIQUE INDEX categories_user_id_name_key ON categories (user_id, lower(name));

CREATE TABLE receipts (
    id             uuid          PRIMARY KEY DEFAULT uuidv7(),
    user_id        uuid          NOT NULL,
    title          text          NOT NULL,
    store_id       uuid,
    purchased_on   date,
    purchased_time time,
    currency       text          NOT NULL,
    subtotal       numeric(12,2),
    tax_total      numeric(12,2),
    total          numeric(12,2),
    status         text          NOT NULL DEFAULT 'queued',
    source         text          NOT NULL DEFAULT 'web',
    failure_reason text,
    created_at     timestamptz   NOT NULL DEFAULT now(),
    updated_at     timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT receipts_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT receipts_user_id_id_key UNIQUE (user_id, id),
    CONSTRAINT receipts_store_fkey FOREIGN KEY (user_id, store_id) REFERENCES stores (user_id, id) ON DELETE SET NULL (store_id),
    CONSTRAINT receipts_title_check CHECK (btrim(title) <> ''),
    CONSTRAINT receipts_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT receipts_status_check CHECK (status IN ('queued', 'processing', 'needs_review', 'ready', 'failed', 'waiting_quota')),
    CONSTRAINT receipts_source_check CHECK (source IN ('web')),
    CONSTRAINT receipts_failure_reason_check CHECK (failure_reason IS NULL OR status = 'failed')
);

-- Receipt list, month filter and monthly reports. Receipts that have no
-- date yet (still being processed) sort first.
CREATE INDEX receipts_user_id_purchased_on_idx ON receipts (user_id, purchased_on DESC NULLS FIRST, id DESC);
-- Status filter and the receipts a report must leave out.
CREATE INDEX receipts_user_id_status_idx ON receipts (user_id, status);
-- "Same store, date and total" lookup behind the possible_duplicate flag.
CREATE INDEX receipts_duplicate_idx ON receipts (user_id, store_id, purchased_on, total);

-- One uploaded file is one receipt in v1; position allows more images later.
-- storage_ref is the JPEG or PNG the pipeline and the UI use. The original_*
-- columns are set only when the upload was converted (HEIC/HEIF).
CREATE TABLE receipt_images (
    id                    uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id               uuid        NOT NULL,
    receipt_id            uuid        NOT NULL,
    position              integer     NOT NULL DEFAULT 0,
    sha256                bytea       NOT NULL,
    content_type          text        NOT NULL,
    size_bytes            bigint      NOT NULL,
    storage_backend       text        NOT NULL,
    storage_ref           text        NOT NULL,
    original_ref          text,
    original_content_type text,
    original_size_bytes   bigint,
    created_at            timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT receipt_images_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT receipt_images_receipt_fkey FOREIGN KEY (user_id, receipt_id) REFERENCES receipts (user_id, id) ON DELETE CASCADE,
    -- The hash is of the uploaded bytes, so the same photo is rejected once per user.
    CONSTRAINT receipt_images_user_id_sha256_key UNIQUE (user_id, sha256),
    CONSTRAINT receipt_images_receipt_id_position_key UNIQUE (receipt_id, position),
    CONSTRAINT receipt_images_position_check CHECK (position >= 0),
    CONSTRAINT receipt_images_sha256_check CHECK (octet_length(sha256) = 32),
    CONSTRAINT receipt_images_content_type_check CHECK (content_type IN ('image/jpeg', 'image/png')),
    CONSTRAINT receipt_images_size_bytes_check CHECK (size_bytes > 0),
    CONSTRAINT receipt_images_storage_backend_check CHECK (storage_backend IN ('local', 'drive')),
    CONSTRAINT receipt_images_storage_ref_check CHECK (storage_ref <> ''),
    CONSTRAINT receipt_images_original_content_type_check CHECK (original_content_type IN ('image/heic', 'image/heif')),
    CONSTRAINT receipt_images_original_size_bytes_check CHECK (original_size_bytes > 0),
    -- All three original_* columns are set together or not at all.
    CONSTRAINT receipt_images_original_check CHECK (
        (original_ref IS NULL) = (original_content_type IS NULL)
        AND (original_ref IS NULL) = (original_size_bytes IS NULL)
        AND original_ref <> ''
    )
);

-- Raw provider results, kept so that mapping and matching can be re-run
-- without spending extraction quota.
CREATE TABLE extractions (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id    uuid        NOT NULL,
    receipt_id uuid        NOT NULL,
    provider   text        NOT NULL,
    model      text        NOT NULL,
    raw        jsonb       NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT extractions_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT extractions_receipt_fkey FOREIGN KEY (user_id, receipt_id) REFERENCES receipts (user_id, id) ON DELETE CASCADE,
    CONSTRAINT extractions_provider_check CHECK (provider IN ('azure', 'fake')),
    CONSTRAINT extractions_model_check CHECK (model <> '')
);

-- Latest extraction of a receipt.
CREATE INDEX extractions_receipt_id_created_at_idx ON extractions (receipt_id, created_at DESC);

CREATE TABLE products (
    id             uuid          PRIMARY KEY DEFAULT uuidv7(),
    user_id        uuid          NOT NULL,
    canonical_name text          NOT NULL,
    category_id    uuid,
    size_value     numeric(12,3),
    size_unit      text,
    created_at     timestamptz   NOT NULL DEFAULT now(),
    updated_at     timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT products_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT products_user_id_id_key UNIQUE (user_id, id),
    -- Deleting a category leaves its products uncategorised.
    CONSTRAINT products_category_fkey FOREIGN KEY (user_id, category_id) REFERENCES categories (user_id, id) ON DELETE SET NULL (category_id),
    CONSTRAINT products_canonical_name_check CHECK (btrim(canonical_name) <> ''),
    -- A size is a value with its unit, or absent altogether.
    CONSTRAINT products_size_check CHECK (
        (size_value IS NULL) = (size_unit IS NULL)
        AND size_value > 0
        AND size_unit <> ''
    )
);

-- Product list ordered by name, and the category filter.
CREATE INDEX products_user_id_canonical_name_idx ON products (user_id, canonical_name, id);
CREATE INDEX products_user_id_category_id_idx ON products (user_id, category_id);

-- A name a product was seen under. store_id is null when the store is not
-- known. The same normalised name may belong to more than one product; the
-- matching rules treat that as ambiguous.
CREATE TABLE product_aliases (
    id              uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id         uuid        NOT NULL,
    product_id      uuid        NOT NULL,
    raw_name        text        NOT NULL,
    normalized_name text        NOT NULL,
    store_id        uuid,
    seen_count      integer     NOT NULL DEFAULT 1,
    last_seen_at    timestamptz NOT NULL DEFAULT now(),
    created_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_aliases_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT product_aliases_user_id_id_key UNIQUE (user_id, id),
    CONSTRAINT product_aliases_product_fkey FOREIGN KEY (user_id, product_id) REFERENCES products (user_id, id) ON DELETE CASCADE,
    CONSTRAINT product_aliases_store_fkey FOREIGN KEY (user_id, store_id) REFERENCES stores (user_id, id) ON DELETE NO ACTION,
    CONSTRAINT product_aliases_product_id_normalized_name_store_id_key UNIQUE NULLS NOT DISTINCT (product_id, normalized_name, store_id),
    CONSTRAINT product_aliases_raw_name_check CHECK (raw_name <> ''),
    CONSTRAINT product_aliases_normalized_name_check CHECK (normalized_name <> ''),
    CONSTRAINT product_aliases_seen_count_check CHECK (seen_count >= 1)
);

-- Candidate lookup by similarity (matching §5.2) and exact alias lookup.
CREATE INDEX product_aliases_normalized_name_trgm_idx ON product_aliases USING gin (normalized_name gin_trgm_ops);
CREATE INDEX product_aliases_user_id_normalized_name_idx ON product_aliases (user_id, normalized_name);

-- A code printed next to a product. A store code only counts inside its
-- store; a GTIN counts everywhere. The same code may be recorded for more
-- than one product; the matching rules route that to the user.
CREATE TABLE product_codes (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id    uuid        NOT NULL,
    product_id uuid        NOT NULL,
    code       text        NOT NULL,
    kind       text        NOT NULL,
    store_id   uuid,
    seen_count integer     NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_codes_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT product_codes_product_fkey FOREIGN KEY (user_id, product_id) REFERENCES products (user_id, id) ON DELETE CASCADE,
    CONSTRAINT product_codes_store_fkey FOREIGN KEY (user_id, store_id) REFERENCES stores (user_id, id) ON DELETE NO ACTION,
    CONSTRAINT product_codes_product_id_code_kind_store_id_key UNIQUE NULLS NOT DISTINCT (product_id, code, kind, store_id),
    CONSTRAINT product_codes_code_check CHECK (code <> ''),
    CONSTRAINT product_codes_kind_check CHECK (kind IN ('gtin', 'store')),
    CONSTRAINT product_codes_store_check CHECK ((kind = 'store') = (store_id IS NOT NULL)),
    CONSTRAINT product_codes_gtin_check CHECK (kind <> 'gtin' OR code ~ '^([0-9]{8}|[0-9]{12}|[0-9]{13})$'),
    CONSTRAINT product_codes_seen_count_check CHECK (seen_count >= 1)
);

-- Products that own a code.
CREATE INDEX product_codes_user_id_code_idx ON product_codes (user_id, code);

-- "The user said this name is not this product."
CREATE TABLE match_rejections (
    id              uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id         uuid        NOT NULL,
    product_id      uuid        NOT NULL,
    normalized_name text        NOT NULL,
    store_id        uuid,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT match_rejections_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT match_rejections_product_fkey FOREIGN KEY (user_id, product_id) REFERENCES products (user_id, id) ON DELETE CASCADE,
    CONSTRAINT match_rejections_store_fkey FOREIGN KEY (user_id, store_id) REFERENCES stores (user_id, id) ON DELETE NO ACTION,
    CONSTRAINT match_rejections_product_id_normalized_name_store_id_key UNIQUE NULLS NOT DISTINCT (product_id, normalized_name, store_id),
    CONSTRAINT match_rejections_normalized_name_check CHECK (normalized_name <> '')
);

-- Rejections for an incoming name.
CREATE INDEX match_rejections_user_id_normalized_name_idx ON match_rejections (user_id, normalized_name);

-- raw_name is what the extractor read; name is the cleaned, editable text.
-- Amounts are nullable because a receipt may not print them; a negative
-- line_total is a discount.
CREATE TABLE line_items (
    id            uuid             PRIMARY KEY DEFAULT uuidv7(),
    user_id       uuid             NOT NULL,
    receipt_id    uuid             NOT NULL,
    position      integer          NOT NULL,
    raw_name      text             NOT NULL,
    name          text             NOT NULL,
    quantity      numeric(12,3),
    quantity_unit text,
    unit_price    numeric(12,2),
    line_total    numeric(12,2),
    product_code  text,
    confidence    double precision,
    product_id    uuid,
    match_status  text             NOT NULL DEFAULT 'unmatched',
    match_score   double precision,
    match_method  text,
    created_at    timestamptz      NOT NULL DEFAULT now(),
    updated_at    timestamptz      NOT NULL DEFAULT now(),
    CONSTRAINT line_items_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT line_items_user_id_id_key UNIQUE (user_id, id),
    CONSTRAINT line_items_receipt_fkey FOREIGN KEY (user_id, receipt_id) REFERENCES receipts (user_id, id) ON DELETE CASCADE,
    -- A product cannot disappear under its purchases: merge moves them first.
    CONSTRAINT line_items_product_fkey FOREIGN KEY (user_id, product_id) REFERENCES products (user_id, id) ON DELETE NO ACTION,
    -- Deferrable, so that lines can be renumbered in one statement.
    CONSTRAINT line_items_receipt_id_position_key UNIQUE (receipt_id, position) DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT line_items_position_check CHECK (position >= 0),
    CONSTRAINT line_items_name_check CHECK (btrim(name) <> ''),
    CONSTRAINT line_items_quantity_unit_check CHECK (quantity_unit <> ''),
    CONSTRAINT line_items_product_code_check CHECK (product_code <> ''),
    CONSTRAINT line_items_confidence_check CHECK (confidence >= 0 AND confidence <= 1),
    CONSTRAINT line_items_match_status_check CHECK (match_status IN ('unmatched', 'needs_review', 'auto_linked', 'new_product', 'confirmed')),
    CONSTRAINT line_items_match_score_check CHECK (match_score >= 0 AND match_score <= 1),
    CONSTRAINT line_items_match_method_check CHECK (match_method IN ('alias', 'code', 'similarity', 'user')),
    -- A line has a product exactly when matching or the user decided on one.
    CONSTRAINT line_items_product_check CHECK ((product_id IS NULL) = (match_status IN ('unmatched', 'needs_review')))
);

-- Purchases of a product (price history, merge and split).
CREATE INDEX line_items_user_id_product_id_idx ON line_items (user_id, product_id) WHERE product_id IS NOT NULL;

-- Something on a receipt that a person should look at. detail holds what the
-- rule saw; resolution records how the flag was closed.
CREATE TABLE review_flags (
    id           uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id      uuid        NOT NULL,
    receipt_id   uuid        NOT NULL,
    line_item_id uuid,
    kind         text        NOT NULL,
    detail       jsonb       NOT NULL DEFAULT '{}',
    resolved_at  timestamptz,
    resolution   text,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT review_flags_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT review_flags_receipt_fkey FOREIGN KEY (user_id, receipt_id) REFERENCES receipts (user_id, id) ON DELETE CASCADE,
    CONSTRAINT review_flags_line_item_fkey FOREIGN KEY (user_id, line_item_id) REFERENCES line_items (user_id, id) ON DELETE CASCADE,
    CONSTRAINT review_flags_kind_check CHECK (kind IN (
        'low_confidence', 'missing_field', 'line_math', 'sum_mismatch',
        'uncertain_match', 'code_conflict', 'possible_duplicate'
    )),
    CONSTRAINT review_flags_detail_check CHECK (jsonb_typeof(detail) = 'object'),
    -- 'superseded' closes a flag whose cause went away when the data changed.
    CONSTRAINT review_flags_resolution_check CHECK (resolution IN (
        'confirmed', 'corrected', 'same_product', 'different_product', 'accepted', 'superseded'
    )),
    CONSTRAINT review_flags_resolved_check CHECK ((resolved_at IS NULL) = (resolution IS NULL))
);

-- Open flags of a user, oldest receipt first, and the open-flag count of a
-- receipt (receipt ids sort by upload time).
CREATE INDEX review_flags_open_idx ON review_flags (user_id, receipt_id, id) WHERE resolved_at IS NULL;
CREATE INDEX review_flags_receipt_id_idx ON review_flags (receipt_id);
CREATE INDEX review_flags_line_item_id_idx ON review_flags (line_item_id) WHERE line_item_id IS NOT NULL;

-- Work queue, claimed oldest first with FOR UPDATE SKIP LOCKED. Not owned by
-- a user: the payload names what the job works on.
CREATE TABLE jobs (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    kind       text        NOT NULL,
    payload    jsonb       NOT NULL DEFAULT '{}',
    status     text        NOT NULL DEFAULT 'queued',
    attempts   integer     NOT NULL DEFAULT 0,
    run_after  timestamptz NOT NULL DEFAULT now(),
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT jobs_kind_check CHECK (kind IN ('extract_receipt')),
    CONSTRAINT jobs_payload_check CHECK (jsonb_typeof(payload) = 'object'),
    CONSTRAINT jobs_status_check CHECK (status IN ('queued', 'running', 'succeeded', 'failed')),
    CONSTRAINT jobs_attempts_check CHECK (attempts >= 0)
);

-- The next runnable job.
CREATE INDEX jobs_queued_idx ON jobs (created_at, id) WHERE status = 'queued';

-- Pages sent to an extraction provider per calendar month (UTC). The quota
-- belongs to the instance, not to a user.
CREATE TABLE provider_usage (
    provider   text        NOT NULL,
    period     text        NOT NULL,
    pages      integer     NOT NULL DEFAULT 0,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT provider_usage_pkey PRIMARY KEY (provider, period),
    CONSTRAINT provider_usage_provider_check CHECK (provider IN ('azure', 'fake')),
    CONSTRAINT provider_usage_period_check CHECK (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
    CONSTRAINT provider_usage_pages_check CHECK (pages >= 0)
);

-- The instance's connection to external image storage, made by the admin.
-- At most one row per backend, and only Drive needs a connection. The
-- refresh token is stored encrypted (ARCHITECTURE §5.5).
CREATE TABLE storage_connections (
    id                      uuid        PRIMARY KEY DEFAULT uuidv7(),
    backend                 text        NOT NULL,
    connected_by            uuid,
    encrypted_refresh_token text        NOT NULL,
    root_folder_ref         text        NOT NULL,
    status                  text        NOT NULL DEFAULT 'connected',
    last_error              text,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT storage_connections_backend_key UNIQUE (backend),
    -- The connection outlives the account of the admin who made it.
    CONSTRAINT storage_connections_connected_by_fkey FOREIGN KEY (connected_by) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT storage_connections_backend_check CHECK (backend IN ('drive')),
    CONSTRAINT storage_connections_encrypted_refresh_token_check CHECK (encrypted_refresh_token <> ''),
    CONSTRAINT storage_connections_root_folder_ref_check CHECK (root_folder_ref <> ''),
    CONSTRAINT storage_connections_status_check CHECK (status IN ('connected', 'reconnect_needed'))
);

-- OAuth 2.1 authorization server state for MCP clients (ARCHITECTURE §5.6).
-- Clients are public and registered dynamically; the id is the client_id.
CREATE TABLE oauth_clients (
    id            uuid        PRIMARY KEY DEFAULT uuidv7(),
    name          text        NOT NULL,
    redirect_uris text[]      NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_used_at  timestamptz,
    CONSTRAINT oauth_clients_redirect_uris_check CHECK (cardinality(redirect_uris) >= 1)
);

-- Authorization codes: single use, short lived, bound to everything the
-- token request must repeat. Only the SHA-256 hash of a code is stored.
CREATE TABLE oauth_codes (
    code_hash      bytea       PRIMARY KEY,
    client_id      uuid        NOT NULL,
    user_id        uuid        NOT NULL,
    redirect_uri   text        NOT NULL,
    code_challenge text        NOT NULL,
    resource       text        NOT NULL,
    scope          text        NOT NULL DEFAULT '',
    expires_at     timestamptz NOT NULL,
    used_at        timestamptz,
    created_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT oauth_codes_client_id_fkey FOREIGN KEY (client_id) REFERENCES oauth_clients (id) ON DELETE CASCADE,
    CONSTRAINT oauth_codes_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT oauth_codes_code_hash_check CHECK (octet_length(code_hash) = 32),
    CONSTRAINT oauth_codes_code_challenge_check CHECK (code_challenge <> '')
);

CREATE INDEX oauth_codes_expires_at_idx ON oauth_codes (expires_at);

-- Access and refresh tokens, stored as SHA-256 hashes. Every token issued
-- from one authorization shares a grant_id, so that reuse of a rotated
-- refresh token can revoke the whole grant.
CREATE TABLE oauth_tokens (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    grant_id   uuid        NOT NULL,
    client_id  uuid        NOT NULL,
    user_id    uuid        NOT NULL,
    kind       text        NOT NULL,
    token_hash bytea       NOT NULL,
    resource   text        NOT NULL,
    scope      text        NOT NULL DEFAULT '',
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT oauth_tokens_client_id_fkey FOREIGN KEY (client_id) REFERENCES oauth_clients (id) ON DELETE CASCADE,
    CONSTRAINT oauth_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT oauth_tokens_token_hash_key UNIQUE (token_hash),
    CONSTRAINT oauth_tokens_kind_check CHECK (kind IN ('access', 'refresh')),
    CONSTRAINT oauth_tokens_token_hash_check CHECK (octet_length(token_hash) = 32)
);

CREATE INDEX oauth_tokens_grant_id_idx ON oauth_tokens (grant_id);
CREATE INDEX oauth_tokens_user_id_idx ON oauth_tokens (user_id);
CREATE INDEX oauth_tokens_client_id_idx ON oauth_tokens (client_id);

-- What a user changed, with before and after values in detail.
CREATE TABLE audit_events (
    id         uuid        PRIMARY KEY DEFAULT uuidv7(),
    user_id    uuid        NOT NULL,
    entity     text        NOT NULL,
    entity_id  uuid        NOT NULL,
    action     text        NOT NULL,
    detail     jsonb       NOT NULL DEFAULT '{}',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT audit_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT audit_events_entity_check CHECK (entity IN (
        'receipt', 'line_item', 'review_flag', 'product', 'store', 'category', 'settings'
    )),
    CONSTRAINT audit_events_action_check CHECK (action ~ '^[a-z][a-z_]*$'),
    CONSTRAINT audit_events_detail_check CHECK (jsonb_typeof(detail) = 'object')
);

-- History of one entity.
CREATE INDEX audit_events_entity_idx ON audit_events (user_id, entity, entity_id, created_at);

-- +goose Down

DROP TABLE audit_events;
DROP TABLE oauth_tokens;
DROP TABLE oauth_codes;
DROP TABLE oauth_clients;
DROP TABLE storage_connections;
DROP TABLE provider_usage;
DROP TABLE jobs;
DROP TABLE review_flags;
